import React, { useState, useEffect } from 'react'
import { FolderOpen, Plus, RefreshCw } from 'lucide-react'
import { api, type ProjectInfo } from '@/lib/api'

interface ProjectPanelProps {
  selectedProjectId: string | null
  onProjectSelect: (projectId: string | null) => void
}

const statusColors: Record<string, string> = {
  draft: 'bg-slate-400',
  active: 'bg-green-500',
  paused: 'bg-yellow-500',
  completed: 'bg-blue-500',
  cancelled: 'bg-red-400',
}

const statusLabels: Record<string, string> = {
  draft: '草稿',
  active: '执行中',
  paused: '已暂停',
  completed: '已完成',
  cancelled: '已取消',
}

export function ProjectPanel({ selectedProjectId, onProjectSelect }: ProjectPanelProps) {
  const [projects, setProjects] = useState<ProjectInfo[]>([])
  const [loading, setLoading] = useState(false)
  const [filter, setFilter] = useState<'all' | 'active' | 'completed'>('all')
  const [showCreateInput, setShowCreateInput] = useState(false)
  const [newTitle, setNewTitle] = useState('')
  const [newRepoUrl, setNewRepoUrl] = useState('')

  const loadProjects = async () => {
    setLoading(true)
    try {
      const data = await api.getProjects()
      setProjects(data.items || [])
    } catch (err) {
      console.error('加载项目失败:', err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadProjects()
  }, [])

  const handleCreate = async () => {
    if (!newTitle.trim()) return
    try {
      const project = await api.createProject({
        title: newTitle.trim(),
        repo_url: newRepoUrl.trim() || undefined,
      })
      setProjects(prev => [project, ...prev])
      setNewTitle('')
      setNewRepoUrl('')
      setShowCreateInput(false)
      onProjectSelect(project.id)
    } catch (err) {
      console.error('创建项目失败:', err)
    }
  }

  const filteredProjects = projects.filter(p => {
    if (filter === 'active') return p.status === 'active'
    if (filter === 'completed') return p.status === 'completed'
    return true
  })

  return (
    <div className="flex h-full flex-col bg-background">
      {/* 标题栏 */}
      <div className="flex items-center gap-1.5 px-3 py-2 border-b shrink-0">
        <FolderOpen className="h-3.5 w-3.5 text-muted-foreground" />
        <span className="text-xs font-medium">项目</span>
        {filteredProjects.length > 0 && (
          <span className="rounded-full bg-primary/10 text-primary px-1.5 py-0.5 text-[10px]">
            {filteredProjects.length}
          </span>
        )}
        <div className="ml-auto flex items-center gap-1">
          <select
            value={filter}
            onChange={(e) => setFilter(e.target.value as 'all' | 'active' | 'completed')}
            className="h-5 text-[10px] rounded border bg-background px-1 text-muted-foreground"
          >
            <option value="all">全部</option>
            <option value="active">执行中</option>
            <option value="completed">已完成</option>
          </select>
          <button
            onClick={loadProjects}
            className="h-5 w-5 flex items-center justify-center rounded hover:bg-accent text-muted-foreground hover:text-foreground transition-colors"
            title="刷新"
          >
            <RefreshCw className={`h-3 w-3 ${loading ? 'animate-spin' : ''}`} />
          </button>
          <button
            onClick={() => setShowCreateInput(!showCreateInput)}
            className="h-5 w-5 flex items-center justify-center rounded hover:bg-accent text-muted-foreground hover:text-foreground transition-colors"
            title="新建项目"
          >
            <Plus className="h-3 w-3" />
          </button>
        </div>
      </div>

      {/* 内联创建输入框 */}
      {showCreateInput && (
        <div className="px-3 py-2 border-b bg-accent/20">
          <div className="flex flex-col gap-1.5">
            <input
              value={newTitle}
              onChange={(e) => setNewTitle(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleCreate()}
              placeholder="项目标题..."
              className="flex-1 h-6 text-xs rounded border bg-background px-2 placeholder:text-muted-foreground/50"
              autoFocus
            />
            <input
              value={newRepoUrl}
              onChange={(e) => setNewRepoUrl(e.target.value)}
              placeholder="Git 仓库地址（可选）..."
              className="flex-1 h-6 text-xs rounded border bg-background px-2 placeholder:text-muted-foreground/50"
            />
            <div className="flex gap-1.5">
              <button
                onClick={handleCreate}
                className="h-6 px-2 text-[10px] rounded bg-primary text-primary-foreground hover:bg-primary/90"
              >
                创建
              </button>
              <button
                onClick={() => { setShowCreateInput(false); setNewTitle(''); setNewRepoUrl('') }}
                className="h-6 px-2 text-[10px] rounded border bg-background hover:bg-accent"
              >
                取消
              </button>
            </div>
          </div>
        </div>
      )}

      {/* 项目列表 */}
      <div className="flex-1 overflow-y-auto">
        {loading && projects.length === 0 ? (
          <div className="flex items-center justify-center h-20 text-xs text-muted-foreground">
            加载中...
          </div>
        ) : filteredProjects.length === 0 ? (
          <div className="flex items-center justify-center h-20 text-xs text-muted-foreground">
            {filter === 'all' ? '暂无项目' : '无匹配项目'}
          </div>
        ) : (
          <div className="py-1">
            {filteredProjects.map(project => (
              <div
                key={project.id}
                onClick={() => onProjectSelect(
                  selectedProjectId === project.id ? null : project.id
                )}
                className={`mx-2 my-0.5 px-2.5 py-2 rounded cursor-pointer transition-colors ${
                  selectedProjectId === project.id
                    ? 'bg-primary/15 border border-primary/30 text-foreground'
                    : 'hover:bg-accent/50 border border-transparent'
                }`}
              >
                <div className="flex items-center gap-2">
                  <span className={`h-2 w-2 rounded-full shrink-0 ${statusColors[project.status] || 'bg-slate-400'}`} />
                  <span className="text-xs font-medium truncate flex-1">
                    {project.title}
                  </span>
                  <span className="text-[10px] text-muted-foreground shrink-0">
                    {statusLabels[project.status] || project.status}
                  </span>
                </div>
                <div className="mt-0.5 text-[10px] text-muted-foreground pl-4">
                  {project.id}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}
